entries[253110] = { ["name"] = "Monel-Hardened Hoofplates", ["text"] = "2 sec cast\nTools: Blacksmith Hammer\nReagents:\nMonelite Ore (25), Durable Flux (2)\nCreate a set of Monel-Hardened Hoofplates.\nProfession:\nBattle for Azeroth Blacksmithing (50)\nTrainer:\nForgemaster Zak'aal\nZone:\nZuldazar\nCost:\n2\n\nUse: Place hoofplates onto your mount, increasing speed while mounted in Kul Tiras or Zandalar by 20% for 2 hrs.\n\nThe effect's duration is quadrupled for blacksmiths." }
entries[253111] = { ["name"] = "Light's Embrace", ["text"] = "Rank 1/ 3 Artifact Trait\nApproximately 8 procs per minute\nTaking damage has a chance to grant you Light's Embrace, restoring 45500 health over 6 sec. Light's Embrace may stack up to 5 times.\n(1s cooldown)" }
