entries[253113] = { ["name"] = "Monel-Hardened Shield", ["text"] = "2.5 sec cast\nTools: Blacksmith Hammer\nReagents:\nMonelite Ore (18), Durable Flux (3)\nOptional Reagents:\nOptional Reagent Slot (#48)\nCreate a Monel-Hardened Shield.\nProfession:\nBattle for Azeroth Blacksmithing (15)\nTrainer:\nForgemaster Zak'aal\nZone:\nZuldazar\nCost:\n50\n\nAlliance\nMonel-Hardened Shield\nBinds when equipped\nOff Hand Shield\n59 Armor\n+3 Strength\n+9 Intellect\n+4 Stamina\nDurability 85 / 85\n45\nHorde\nMonel-Hardened Shield\nBinds when equipped\nOff Hand Shield\n59 Armor\n+3 Strength\n+9 Intellect\n+4 Stamina\nDurability 85 / 85\n45" }
